"""Write generated files: only what changed, prune stale ones, guard ownership."""

from __future__ import annotations

import json
import shutil
from dataclasses import dataclass, field
from pathlib import Path

from lwd import paths
from lwd.config import SiteConfig
from lwd.load import GENERATED_DIRS
from lwd.render import OutputSet

MANIFEST = "generated/manifest.json"


@dataclass
class WriteResult:
    written: list[str] = field(default_factory=list)
    unchanged: int = 0
    pruned: list[str] = field(default_factory=list)
    hand_edited: list[str] = field(default_factory=list)


class OwnershipError(Exception):
    pass


def owned_dirs(cfg: SiteConfig) -> list[Path]:
    return [cfg.docs / d for d in GENERATED_DIRS] + [cfg.root / "generated"]


def _ensure_owned(folder: Path) -> None:
    marker = folder / paths.OWNED_MARKER
    if folder.is_dir() and any(folder.iterdir()) and not marker.is_file():
        raise OwnershipError(f"{folder} exists and is not owned by lwd (no {paths.OWNED_MARKER}); refusing to write into it")
    folder.mkdir(parents=True, exist_ok=True)
    if not marker.is_file():
        marker.write_text("Generated by lwd. Everything in this folder is regenerated by `python -m lwd gen`.\n", encoding="utf-8")


def _encode(content: str | bytes) -> bytes:
    return content if isinstance(content, bytes) else content.replace("\r\n", "\n").encode("utf-8")


def write_outputs(cfg: SiteConfig, outputs: OutputSet) -> WriteResult:
    result = WriteResult()
    for folder in owned_dirs(cfg):
        _ensure_owned(folder)
    manifest_path = cfg.root / MANIFEST
    try:
        old_manifest: dict[str, str] = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        old_manifest = {}
    planned: dict[str, bytes] = {}
    for page, content in outputs.docs.items():
        planned[f"{cfg.docs_dir}/{page}"] = _encode(content)
    for rel, content in outputs.root.items():
        planned[rel] = _encode(content)
    planned[f"generated/README.md"] = b"Everything in generated/ is rebuilt by `python -m lwd gen`. Do not edit.\n"
    new_manifest: dict[str, str] = {}
    for rel, data in sorted(planned.items()):
        target = cfg.root / rel
        digest = paths.sha256(data)
        new_manifest[rel] = digest
        if target.is_file():
            current = target.read_bytes()
            if current == data:
                result.unchanged += 1
                continue
            known = old_manifest.get(rel)
            if known and paths.sha256(current) != known:
                backup = cfg.root / "generated" / "overwritten" / rel
                backup.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(target, backup)
                result.hand_edited.append(rel)
        paths.atomic_write(target, data)
        result.written.append(rel)
    # Prune files in owned directories that are no longer produced.
    keep = set(planned) | {MANIFEST}
    for folder in owned_dirs(cfg):
        for path in sorted(folder.rglob("*"), reverse=True):
            rel = path.relative_to(cfg.root).as_posix()
            if path.is_file():
                if path.name == paths.OWNED_MARKER or rel.startswith("generated/overwritten/"):
                    continue
                if rel not in keep:
                    path.unlink()
                    result.pruned.append(rel)
            elif path.is_dir() and not any(path.iterdir()):
                path.rmdir()
    paths.atomic_write(manifest_path, (json.dumps(new_manifest, indent=1, sort_keys=True) + "\n").encode("utf-8"))
    return result


def clean(cfg: SiteConfig) -> list[str]:
    removed = []
    for folder in owned_dirs(cfg):
        if folder.is_dir() and (folder / paths.OWNED_MARKER).is_file():
            shutil.rmtree(folder)
            removed.append(folder.relative_to(cfg.root).as_posix())
    return removed
